public sealed record ConsolidationSourceAccountSnapshot(Guid CompanyId, string CompanyName, Guid AccountId, string AccountNumber, string AccountName, string AccountType);
public sealed record ConsolidationAccountMappingSnapshot(Guid Id, Guid CompanyId, string CompanyName, Guid AccountId, string AccountNumber, string AccountName, string AccountType, string ReportingAccountNumber, string ReportingAccountName, string ReportingAccountType, string TranslationMethod, DateOnly EffectiveFrom, DateOnly? EffectiveThrough, bool IsActive, string ConcurrencyToken, string CashFlowActivity = "Unclassified", string CashFlowRationale = "", DateOnly? CashFlowReviewedOn = null);
public sealed record ConsolidationAccountMappingWorkspace(Guid GroupId, string GroupName, IReadOnlyList<ConsolidationSourceAccountSnapshot> SourceAccounts, IReadOnlyList<ConsolidationAccountMappingSnapshot> Mappings);
public sealed record SaveConsolidationStatementPresentationRequest(Guid? Id, Guid ConsolidationGroupId, string StatementCode, string ReportingAccountNumber, string ReportingAccountName, string ReportingAccountType, string SectionCode, string SectionName, int SectionSortOrder, string LineCaption, int LineSortOrder, string Rationale, DateOnly ReviewedOn, DateOnly EffectiveFrom, DateOnly? EffectiveThrough, bool IsActive = true, string ConcurrencyToken = "");
